from test_nearby import test,setup
failure="SPELL_FAILED_OUT_OF_RANGE='Out of range'; SPELL_FAILED_LINE_OF_SIGHT='Not in line of sight'; "
prepare=setup+failure+"local action=BuffTap.action; BuffTap:BeginHelperAttempt(action); "
test('Range backoff needs matching failure and reason',prepare+"BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action)); BuffTap:HandleHelperFailure(action.id); assert(BuffTap:CastRetryBlocked(action))")
test('LOS backoff accepts reverse event order',prepare+"BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_LINE_OF_SIGHT); assert(BuffTap:CastRetryBlocked(action))")
test('Range failure alone cannot suppress a recipient',prepare+"BuffTap:HandleHelperFailure(action.id); assert(not BuffTap:CastRetryBlocked(action))")
test('Range message alone cannot suppress a recipient',prepare+"BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Range failure for different spell cannot suppress recipient',prepare+"BuffTap:HandleHelperFailure(999999); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Unrelated mana and cooldown errors cannot suppress recipient',prepare+"BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError('Not enough mana'); assert(not BuffTap:CastRetryBlocked(action)); BuffTap:BeginHelperAttempt(action); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError('Spell is not ready'); assert(not BuffTap:CastRetryBlocked(action))")
test('Old cast attempts do not create backoff',prepare+"now=now+1.1; BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Range backoff is per recipient and exact spell',prepare+"BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked({id=action.id,target='nameplate2',targetGUID='Other'})); assert(not BuffTap:CastRetryBlocked({id=467,target=action.target,targetGUID=action.targetGUID})); assert(BuffTap:HelperSuppressed(action))")
test('Range backoff expires and schedules retry without movement',prepare+"BuffTap.db.buffs.thorns=false; refresh(); action=BuffTap.action; BuffTap:BeginHelperAttempt(action); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); advance(.1); assert(not BuffTap.action); advance(10.2); assert(BuffTap.action and BuffTap.action.target=='nameplate1' and not BuffTap:CastRetryBlocked(action))")
test('Range backoff advances to another nearby recipient',prepare+"BuffTap.db.buffs.thorns=false; BuffTap:TrackNearby('nameplate2'); refresh(); action=BuffTap.action; BuffTap:BeginHelperAttempt(action); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); advance(.1); assert(BuffTap.action and BuffTap.action.target=='nameplate2')")
test('Recycled recipient identity cannot be penalized',prepare+"local old=UnitGUID; UnitGUID=function(u) return u==action.target and 'Recycled' or old(u) end; BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Success clears pending failed-attempt correlation',prepare+"BuffTap:HelperEvent('UNIT_SPELLCAST_SUCCEEDED','player',nil,action.id); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Restore reminders clears temporary retry state',prepare+"BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); BuffTap:RestoreHelpers(); assert(not BuffTap:CastRetryBlocked(action))")
test('Zone transition clears temporary retry state',prepare+"BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); BuffTap:HelperEvent('ZONE_CHANGED_NEW_AREA'); assert(not BuffTap:CastRetryBlocked(action))")
test('Self spells never receive target-error backoff',failure+"local action=BuffTap.action; assert(action.target=='player'); BuffTap:BeginHelperAttempt(action); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE); assert(not BuffTap:CastRetryBlocked(action))")
test('Retry state remains capped at 200 recipients',prepare+"local current; local oldGUID=UnitGUID; UnitGUID=function(u) return u=='nameplate1' and current or oldGUID(u) end; for n=1,220 do current='Player-'..n; local a={id=action.id,target='nameplate1',targetGUID=current}; BuffTap:BeginHelperAttempt(a); BuffTap:HandleHelperFailure(a.id); BuffTap:HandleHelperError(SPELL_FAILED_OUT_OF_RANGE) end; local count=0; for _ in pairs(BuffTap.castRetry) do count=count+1 end; assert(count==200)")
test('Retry delay removes failed hovered recipient from display',prepare+"BuffTap.db.buffs.thorns=false; BuffTap:TrackNearby('nameplate2'); refresh(); action=BuffTap.action; local row=BuffTap.nearbyFrame.rows[1]; row.scripts.OnEnter(row); BuffTap:BeginHelperAttempt(action); BuffTap:HandleHelperFailure(action.id); BuffTap:HandleHelperError(SPELL_FAILED_LINE_OF_SIGHT); advance(.1); assert(BuffTap.nearbyFrame.rows[1].entry.unit=='nameplate2'); assert(not BuffTap.nearbyHovered)")
